def transform(g):
    h,w=len(g),len(g[0])
    # enclosed zeros: flood fill zeros from border (4-conn)
    out=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==0 and not seen[a][b]:
                seen[a][b]=True; dq.append((a,b))
    def nb8(i,j):
        for di in (-1,0,1):
            for dj in (-1,0,1):
                if di==dj==0: continue
                a,b=i+di,j+dj
                if 0<=a<h and 0<=b<w and g[a][b]==1: return True
        return False
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and nb8(i,j):
                out[i][j]= 3 if not seen[i][j] else 2
    return out
